1	using Microsoft.EntityFrameworkCore;
2	using seed_b_backend.Api.Data;
3	using seed_b_backend.Api.Domain;
4	using seed_b_backend.Api.Dtos;
5	
6	namespace seed_b_backend.Api.Application;
7	
8	public class OrderService(AppDbContext db)
9	{
10	    public async Task<OrderCreateResult> CreateOrderAsync(OrderCreateDto request, CancellationToken cancellationToken = default)
11	    {
12	        if (request.Items.Count == 0)
13	        {
14	            return OrderCreateResult.Invalid("Der Warenkorb ist leer.");
15	        }
16	
17	        await using var transaction = await db.Database.BeginTransactionAsync(cancellationToken);
18	
19	        var order = new Order
20	        {
21	            PublicId = Guid.NewGuid(),
22	            Status = OrderStatus.Received,
23	            DeliveryName = request.Delivery.Name,
24	            DeliveryStreet = request.Delivery.Street,
25	            DeliveryPostalCode = request.Delivery.PostalCode,
26	            DeliveryCity = request.Delivery.City,
27	            DeliveryCountry = request.Delivery.Country,
28	            DeliveryEmail = request.Delivery.Email,
29	            DeliveryPhone = request.Delivery.Phone,
30	            CreatedAt = DateTime.UtcNow,
31	        };
32	
33	        var responseItems = new List<OrderItemResponseDto>();
34	        var invalidLines = new List<InvalidLineDto>();
35	
36	        foreach (var line in request.Items)
37	        {
38	            if (line.Quantity < 1)
39	            {
40	                invalidLines.Add(new InvalidLineDto
41	                {
42	                    ProductId = line.ProductId,
43	                    SupplierId = line.SupplierId,
44	                    Reason = OrderRejectionReasons.InvalidQuantity,
45	                });
46	                continue;
47	            }
48	
49	            var offer = await db.Offers
50	                .Where(o => o.ProductId == line.ProductId && o.SupplierId == line.SupplierId)
51	                .Select(o => new { o.Price, ProductName = o.Product.Name, SupplierName = o.Supplier.Name })
52	                .SingleOrDefaultAsync(cancellationToken);
53	
54	            if (offer is null)
55	            {
56	                invalidLines.Add(new InvalidLineDto
57	                {
58	                    ProductId = line.ProductId,
59	                    SupplierId = line.SupplierId,
60	                    Reason = OrderRejectionReasons.OfferNotFound,
61	                });
62	                continue;
63	            }
64	
65	            order.Items.Add(new OrderItem
66	            {
67	                ProductId = line.ProductId,
68	                SupplierId = line.SupplierId,
69	                Quantity = line.Quantity,
70	                UnitPriceAtOrder = offer.Price,
71	            });
72	
73	            responseItems.Add(new OrderItemResponseDto
74	            {
75	                ProductId = line.ProductId,
76	                ProductName = offer.ProductName,
77	                SupplierId = line.SupplierId,
78	                SupplierName = offer.SupplierName,
79	                UnitPrice = offer.Price,
80	                Quantity = line.Quantity,
81	                LineTotal = offer.Price * line.Quantity,
82	            });
83	        }
84	
85	        if (invalidLines.Count > 0)
86	        {
87	            return OrderCreateResult.Invalid("Ihre Bestellung enthält ungültige Positionen.", invalidLines);
88	        }
89	
90	        db.Orders.Add(order);
91	        await db.SaveChangesAsync(cancellationToken);
92	        await transaction.CommitAsync(cancellationToken);
93	
94	        return OrderCreateResult.Ok(new OrderDto
95	        {
96	            PublicId = order.PublicId,
97	            Status = order.Status.ToString(),
98	            Delivery = request.Delivery,
99	            Items = responseItems,
100	            TotalAmount = responseItems.Sum(i => i.LineTotal),
101	            CreatedAt = order.CreatedAt,
102	        });
103	    }
104	}
